BEGIN;
CREATE TABLE IF NOT EXISTS digimon(number integer primary key,slug text unique not null,name text not null,generation text not null,attribute text not null,type text not null,base_personality text,ridable boolean not null,stats jsonb not null,evolution_condition jsonb not null);
CREATE TABLE IF NOT EXISTS evolution(from_slug text not null references digimon(slug),to_slug text not null references digimon(slug),requirements jsonb not null,primary key(from_slug,to_slug));
TRUNCATE evolution,digimon;
COMMIT;
